//! Tray icon: closing the window only hides it, so notifications keep arriving.
use tauri::{
    image::Image,
    menu::{Menu, MenuItem, PredefinedMenuItem},
    tray::{MouseButton, MouseButtonState, TrayIconBuilder, TrayIconEvent},
    AppHandle, Manager,
};

use crate::{open_setup, show_main, MAIN};

const TRAY: &str = "main";
/// App icon with a red dot (generated by scripts/icons.mjs).
const UNREAD_ICON: &[u8] = include_bytes!("../icons/tray-unread.png");

pub fn create(app: &AppHandle) -> tauri::Result<()> {
    let open = MenuItem::with_id(app, "open", "เปิด Hotline", true, None::<&str>)?;
    let server = MenuItem::with_id(app, "server", "เปลี่ยนเซิร์ฟเวอร์…", true, None::<&str>)?;
    let quit = MenuItem::with_id(app, "quit", "ออก", true, None::<&str>)?;
    let menu = Menu::with_items(app, &[&open, &server, &PredefinedMenuItem::separator(app)?, &quit])?;

    TrayIconBuilder::with_id(TRAY)
        .icon(app.default_window_icon().expect("bundle icon").clone())
        .tooltip("Hotline")
        .menu(&menu)
        .show_menu_on_left_click(false)
        .on_menu_event(|app, event| match event.id.as_ref() {
            "open" => show_or_setup(app),
            "server" => open_setup(app),
            "quit" => app.exit(0),
            _ => {}
        })
        .on_tray_icon_event(|tray, event| {
            if let TrayIconEvent::Click { button: MouseButton::Left, button_state: MouseButtonState::Up, .. } = event {
                toggle_main(tray.app_handle());
            }
        })
        .build(app)?;
    Ok(())
}

fn show_or_setup(app: &AppHandle) {
    match app.get_webview_window(MAIN) {
        Some(_) => show_main(app),
        None => open_setup(app),
    }
}

fn toggle_main(app: &AppHandle) {
    match app.get_webview_window(MAIN) {
        Some(win) if win.is_visible().unwrap_or(false) && win.is_focused().unwrap_or(false) => {
            let _ = win.hide();
        }
        _ => show_or_setup(app),
    }
}

pub fn set_unread(app: &AppHandle, count: u32) {
    let Some(tray) = app.tray_by_id(TRAY) else { return };
    let tooltip = if count == 0 { "Hotline".to_string() } else { format!("Hotline — รอรับเรื่อง {count}") };
    let _ = tray.set_tooltip(Some(tooltip));
    let icon = if count == 0 { app.default_window_icon().cloned() } else { Image::from_bytes(UNREAD_ICON).ok() };
    let _ = tray.set_icon(icon);
}
